"""사고력 수학 문제 원본 (2026-10-07) — 영역 7가지 × 쉬움·보통·도전 × 5문제 = 105문제

문제 하나: Q(단계, 문제 글, 답, 생각 열쇠 3개, 풀이, fig=그림, chk=답을 따로 계산하는 함수, tag=전략 이름)
답: N(수, 단위) · PICK([보기], 정답) · NUMS([(칸 이름, 수), …])
chk가 있으면 build.py가 그 함수로 계산한 답과 적어 둔 답이 같은지 확인합니다(빈칸 셈은 blanks.py로 답이 하나뿐인지도).
"""
from itertools import permutations, product, combinations
from math import comb
import figs
from blanks import blank_solutions, letter_solutions

def N(v, u=''): return {'t': 'num', 'v': v, 'u': u}
def PICK(o, v): return {'t': 'pick', 'o': o, 'v': v}
def NUMS(f): return {'t': 'nums', 'f': [{'l': l, 'v': v} for l, v in f]}
def Q(lv, q, a, k, s, fig=None, chk=None, tag=None):
    return {'lv': lv, 'q': q, 'a': a, 'k': k, 's': s, 'fig': fig, 'chk': chk, 'tag': tag}

def only(sols):   # 답이 딱 하나일 때 그 답
    assert len(sols) == 1, sols
    return sols[0]

def seq_next(xs, f, start=1):   # 규칙 f로 다음 수를 구해 앞 수들도 맞는지 확인(start번째 수부터)
    for i in range(start, len(xs)): assert f(xs[:i]) == xs[i], (xs, i)
    return f(xs)

def perms_where(names, cond):
    return [dict(zip(names, p)) for p in permutations(range(len(names))) if cond(dict(zip(names, p)))]

def angle(h, m):
    d = abs((h % 12) * 30 + m * 0.5 - m * 6) % 360
    return min(d, 360 - d)

